// Produce a non-executable four-row review packet. No database access or writes.
import fs from 'node:fs';import path from 'node:path';import crypto from 'node:crypto';import assert from 'node:assert/strict';import {fileURLToPath} from 'node:url';
const dir=path.dirname(fileURLToPath(import.meta.url)),read=n=>fs.readFileSync(path.join(dir,n)),json=n=>JSON.parse(read(n)),sha=b=>crypto.createHash('sha256').update(b).digest('hex');
const pre=json('four-species-preflight-20261119.json'),review=json('evidence-review-20261119.json'),master=json('master-index-resolution-verified-20261119.json'),hashProbe=json('four-identity-hash-probe-20261119.json');
assert.equal(pre.sanity.read_only,'on');assert.equal(pre.targets.length,4);assert.equal(pre.parents.length,4);assert.equal(pre.identity.length,4);assert.equal(pre.links.length,4);assert.equal(pre.species.length,4);assert.equal(master.all_shards_and_dataset_fingerprint_verified,true);
const expected=new Map([['GV-PK-JPN-DP4-054',{ja:'サンダース',en:'Jolteon',dex:135,old:'zapdos'}],['GV-PK-JPN-DP4-064',{ja:'マタドガス',en:'Weezing',dex:110,old:'unown'}],['GV-PK-JPN-DP4-075',{ja:'ハブネーク',en:'Seviper',dex:336,old:'unown'}],['GV-PK-JPN-DP4-078',{ja:'マンキー',en:'Mankey',dex:56,old:'makuhita'}]]);
const rows=[];for(const t of pre.targets){const e=expected.get(t.gv_id);assert.ok(e);assert.equal(t.japanese_name,e.ja);assert.equal(t.expected_english,e.en);assert.equal(t.expected_dex,e.dex);assert.equal(t.actual_species,e.old);const p=pre.parents.find(x=>x.record.gv_id===t.gv_id)?.record;assert.ok(p);const i=pre.identity.filter(x=>x.record.card_print_id===p.id).map(x=>x.record),l=pre.links.filter(x=>x.record.card_print_id===p.id).map(x=>x.record),s=pre.species.filter(x=>x.record.national_dex_number===e.dex).map(x=>x.record);assert.equal(i.length,1);assert.equal(l.length,1);assert.equal(s.length,1);assert.equal(p.name,e.ja);assert.equal(p.set_code,'jpn-dp4');assert.equal(i[0].is_active,true);assert.equal(i[0].identity_domain,'pokemon_jpn');assert.deepEqual(i[0].identity_payload.card_name_ja_candidates,[e.ja]);assert.equal(l[0].active,true);assert.equal(l[0].role,'primary');assert.equal(l[0].counts_for_completion,true);assert.equal(s[0].active,true);assert.equal(s[0].is_form,false);const c=review.candidates.find(x=>x.card_print_id===p.id);assert.ok(c);const page=read(`official-captures/${c.official_id}.html`),im=read(`official-captures/${c.official_id}.jpg`);assert.equal(sha(page),c.official_page_sha256);assert.equal(sha(im),c.image_sha256);const number=page.toString('utf8').match(/<h4>\s*No\.(\d+)\s*[^<]*<\/h4>/i);assert.ok(number);assert.equal(Number(number[1]),e.dex);const hp=hashProbe.rows.find(x=>x.gv_id===t.gv_id);assert.ok(hp);assert.equal(hp.identity_key_hash,hp.computed_before);assert.equal(hp.computed_before,hp.computed_after);const mr=master.resolutions.find(x=>x.id===p.id);assert.equal(mr?.final_disposition,'master_admissible');assert.equal(mr?.conflict_status,'none');rows.push({gv_id:t.gv_id,expected_species:e,source:c,parent_before:p,identity_before:i[0],old_link_before:l[0],target_species_before:s[0],identity_hash_probe:hp,new_link_id:crypto.randomUUID()});}
rows.sort((a,b)=>a.gv_id.localeCompare(b.gv_id));assert.equal(rows.length,4);const packet={version:'JPN_DP4_SUBJECT_REPAIR_REVIEW_PACKET_V1',created_at:new Date().toISOString(),status:'non_executable_review_only',scope:'Four source-backed species flags; this packet does not register or authorize a writer, freeze current source ownership, prove rollback, or permit database changes.',source_preflight_sha256:sha(read('four-species-preflight-20261119.json')),evidence_review_sha256:sha(read('evidence-review-20261119.json')),master_review_sha256:sha(read('master-index-resolution-verified-20261119.json')),identity_hash_probe_sha256:sha(read('four-identity-hash-probe-20261119.json')),rows};const out=JSON.stringify(packet,null,2)+'\n';fs.writeFileSync(path.join(dir,'four-subject-repair-review-packet-20261119.json'),out,{flag:'wx'});console.log(JSON.stringify({status:packet.status,rows:rows.length,sha256:sha(Buffer.from(out))}));
